public bool CheckTermScript(int[] terms)
		{
			long num = 0L;
			num = 0L;
			int num2 = terms[1];
			int num3 = 2;
			bool flag = true;
			switch (num2)
			{
			case 0:
				flag = false;
				break;
			case 1:
				num = save_.lngs[0];
				break;
			case 2:
				flag = CheckAlreadyEvent(terms[num3++]);
				break;
			case 3:
				num = save_.ints[1] + 1;
				break;
			case 4:
				num = save_.ints[2] + 1;
				break;
			case 5:
				num = save_.ints[3] + 1;
				break;
			case 6:
				if (frmSoccer_.game_sec / 6 == terms[2])
				{
					return true;
				}
				return false;
			case 7:
			{
				int rankIndex = udat_.GetRankIndex();
				if (rankIndex + 1 >= terms[2])
				{
					return true;
				}
				return false;
			}
			case 8:
			{
				int num7 = udat_.matchResult_[0] + udat_.matchResult_[1] + udat_.matchResult_[2];
				if (num7 >= terms[2])
				{
					return true;
				}
				return false;
			}
			case 9:
			{
				int num6 = udat_.matchResult_[0];
				if (num6 >= terms[2])
				{
					return true;
				}
				return false;
			}
			case 10:
			{
				int num5 = udat_.matchResult_[1];
				if (num5 >= terms[2])
				{
					return true;
				}
				return false;
			}
			case 11:
			{
				int num4 = udat_.matchResult_[2];
				if (num4 >= terms[2])
				{
					return true;
				}
				return false;
			}
			case 12:
			{
				int fanDispParam = FanActData.GetFanDispParam(FanActData.GetFanEva(0), 0);
				if (fanDispParam >= terms[2])
				{
					return true;
				}
				return false;
			}
			}
			if (flag && num3 < terms.Length)
			{
				flag = terms[num3] <= num && (terms.Length <= num3 + 1 || num <= terms[num3 + 1]);
			}
			if (terms[0] == 1)
			{
				flag = !flag;
			}
			if (!flag)
			{
				return false;
			}
			return true;
		}

